1	"use client";
2	
3	import { useState, useEffect, useCallback, useMemo } from "react";
4	import Link from "next/link";
5	
6	type TransactionSource =
7	  | "option"
8	  | "manual"
9	  | "adjustment"
10	  | "contest_entry"
11	  | "deposit"
12	  | "withdrawal"
13	  | "winnings"
14	  | "credit"
15	  | "expense";
16	
17	interface Transaction {
18	  id: string;
19	  trip_id: string | null;
20	  trip_name: string | null;
21	  trip_year: number | null;
22	  financial_contest_id: string | null;
23	  contest_name: string | null;
24	  type: "charge" | "payment";
25	  source: TransactionSource;
26	  description: string;
27	  amount: number;
28	  method: string | null;
29	  notes: string | null;
30	  created_at: string;
31	}
32	
33	interface FinancialData {
34	  balance: {
35	    total_charges: number;
36	    total_payments: number;
37	    balance: number;
38	  };
39	  transactions: Transaction[];
40	}
41	
42	// Category label + color for each source. `option` intentionally omitted — the
43	// description ("Breakfast", "Green fees", etc.) already tells you what it is.
44	// `manual` is also omitted: legacy `manual` payments are treated as deposits
45	// via effectiveSource() below; manual charges render without a pill.
46	const CATEGORY: Partial<Record<TransactionSource, { label: string; className: string }>> = {
47	  deposit:        { label: "Deposit",    className: "bg-green-100 text-green-800" },
48	  withdrawal:     { label: "Withdrawal", className: "bg-rose-100 text-rose-800" },
49	  winnings:       { label: "Winnings",   className: "bg-emerald-100 text-emerald-800" },
50	  credit:         { label: "Credit",     className: "bg-sky-100 text-sky-800" },
51	  expense:        { label: "Expense",    className: "bg-amber-100 text-amber-800" },
52	  contest_entry:  { label: "Entry",      className: "bg-violet-100 text-violet-800" },
53	  adjustment:     { label: "Adjustment", className: "bg-gray-100 text-gray-700" },
54	};
55	
56	function effectiveSource(t: Transaction): TransactionSource {
57	  if (t.source === "manual" && t.type === "payment") return "deposit";
58	  return t.source;
59	}
60	
61	const DATE_RANGES = [
62	  { value: "all", label: "All time" },
63	  { value: "30d", label: "Last 30 days" },
64	  { value: "90d", label: "Last 90 days" },
65	  { value: "ytd", label: "This year" },
66	] as const;
67	type DateRangeValue = (typeof DATE_RANGES)[number]["value"];
68	
69	function formatDate(dateStr: string): string {
70	  const d = new Date(dateStr);
71	  return d.toLocaleDateString("en-US", {
72	    month: "short",
73	    day: "numeric",
74	    year: "numeric",
75	  });
76	}
77	
78	function formatCurrency(amount: number): string {
79	  return new Intl.NumberFormat("en-US", {
80	    style: "currency",
81	    currency: "USD",
82	  }).format(Math.abs(amount));
83	}
84	
85	function startOfRange(range: DateRangeValue): Date | null {
86	  const now = new Date();
87	  if (range === "all") return null;
88	  if (range === "30d") {
89	    const d = new Date(now);
90	    d.setDate(d.getDate() - 30);
91	    return d;
92	  }
93	  if (range === "90d") {
94	    const d = new Date(now);
95	    d.setDate(d.getDate() - 90);
96	    return d;
97	  }
98	  if (range === "ytd") return new Date(now.getFullYear(), 0, 1);
99	  return null;
100	}
101	
102	export default function MyFinancials({ userId }: { userId: string }) {
103	  void userId;
104	  const [data, setData] = useState<FinancialData | null>(null);
105	  const [loading, setLoading] = useState(true);
106	  const [error, setError] = useState<string | null>(null);
107	  const [sheikerAvatar, setSheikerAvatar] = useState<string | null>(null);
108	
109	  // Filter state
110	  const [search, setSearch] = useState("");
111	  const [dateRange, setDateRange] = useState<DateRangeValue>("all");
112	  const [activeSources, setActiveSources] = useState<Set<TransactionSource>>(new Set());
113	
114	  const fetchData = useCallback(async () => {
115	    try {
116	      setLoading(true);
117	      const [res, profileRes] = await Promise.all([
118	        fetch("/api/financials/me"),
119	        fetch("/api/loozers/eeaee876-c596-4cc7-91c3-e96b63ecad0c"),
120	      ]);
121	      if (!res.ok) {
122	        const body = await res.json();
123	        throw new Error(body.error || "Failed to load financials");
124	      }
125	      const json: FinancialData = await res.json();
126	      setData(json);
127	      if (profileRes.ok) {
128	        const profileData = await profileRes.json();
129	        setSheikerAvatar(profileData.profile?.avatar_url || null);
130	      }
131	    } catch (err) {
132	      setError(err instanceof Error ? err.message : "Unknown error");
133	    } finally {
134	      setLoading(false);
135	    }
136	  }, []);
137	
138	  useEffect(() => {
139	    fetchData();
140	  }, [fetchData]);
141	
142	  // Sources actually present in the user's transactions — only show pills for these
143	  const availableSources = useMemo<TransactionSource[]>(() => {
144	    if (!data) return [];
145	    const seen = new Set<TransactionSource>();
146	    for (const t of data.transactions) {
147	      const src = effectiveSource(t);
148	      if (CATEGORY[src]) seen.add(src);
149	    }
150	    // Preserve the display order defined in CATEGORY
151	    return (Object.keys(CATEGORY) as TransactionSource[]).filter((s) => seen.has(s));
152	  }, [data]);
153	
154	  // Filter transactions against all three filter controls
155	  const filtered = useMemo(() => {
156	    if (!data) return [];
157	    const rangeStart = startOfRange(dateRange);
158	    const searchLower = search.trim().toLowerCase();
159	    return data.transactions.filter((t) => {
160	      if (rangeStart && new Date(t.created_at) < rangeStart) return false;
161	      if (activeSources.size > 0 && !activeSources.has(effectiveSource(t))) return false;
162	      if (searchLower) {
163	        const hay = `${t.description} ${t.notes ?? ""}`.toLowerCase();
164	        if (!hay.includes(searchLower)) return false;
165	      }
166	      return true;
167	    });
168	  }, [data, dateRange, search, activeSources]);
169	
170	  const toggleSource = (source: TransactionSource) => {
171	    setActiveSources((prev) => {
172	      const next = new Set(prev);
173	      if (next.has(source)) next.delete(source);
174	      else next.add(source);
175	      return next;
176	    });
177	  };
178	
179	  const clearFilters = () => {
180	    setSearch("");
181	    setDateRange("all");
182	    setActiveSources(new Set());
183	  };
184	
185	  const filtersActive = search !== "" || dateRange !== "all" || activeSources.size > 0;
186	
187	  if (loading) {
188	    return (
189	      <div className="flex items-center justify-center py-12">
190	        <div className="w-8 h-8 border-4 border-green-600 border-t-transparent rounded-full animate-spin" />
191	      </div>
192	    );
193	  }
194	
195	  if (error) {
196	    return (
197	      <div className="text-center py-12 text-red-600">
198	        <p>{error}</p>
199	      </div>
200	    );
201	  }
202	
203	  if (!data || data.transactions.length === 0) {
204	    return (
205	      <div className="text-center py-12 text-gray-500">
206	        <p>No financial activity yet.</p>
207	      </div>
208	    );
209	  }
210	
211	  const { balance } = data;
212	  const isNegative = balance.balance < 0;
213	
214	  return (
215	    <div className="space-y-6">
216	      {/* Balance Card */}
217	      <div className="bg-white rounded-2xl border border-gray-200 shadow-sm p-5">
218	        <p className="text-sm text-gray-500 mb-1">
219	          {isNegative ? "Balance Due" : balance.balance > 0 ? "You have a credit" : "All settled up"}
220	        </p>
221	        <p
222	          className={`text-3xl font-bold ${
223	            isNegative ? "text-red-700" : balance.balance > 0 ? "text-green-700" : "text-gray-900"
224	          }`}
225	        >
226	          {isNegative ? "-" : ""}
227	          {formatCurrency(balance.balance)}
228	        </p>
229	      </div>
230	
231	      {/* Venmo Payment Button */}
232	      {isNegative && (() => {
233	        const amountOwed = Math.abs(balance.balance).toFixed(2);
234	        const venmoDeepLink = `venmo://paycharge?txn=pay&recipients=michael-long-194&amount=${amountOwed}&note=${encodeURIComponent("Golfapalooza")}`;
235	        const venmoWebLink = `https://venmo.com/michael-long-194?txn=pay&amount=${amountOwed}&note=${encodeURIComponent("Golfapalooza")}`;
236	        return (
237	          <div className="space-y-2">
238	            <a
239	              href={venmoDeepLink}
240	              onClick={() => {
241	                setTimeout(() => { window.open(venmoWebLink, "_blank"); }, 500);
242	              }}
