7	// GET - Balances data: all users with lifetime financial summaries
8	export async function GET() {
9	  const admin = await checkPermissionAccess("manage_finances");
10	  if (!admin) {
11	    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
12	  }
13	
14	  try {
15	    const adminClient = createAdminClient();
16	
17	    // Fetch all data in parallel
18	    const [
19	      contestsResult,
20	      tripsResult,
21	      txnResult,
22	      usersResult,
23	      contestParticipantsResult,
24	      eventParticipantsResult,
25	      activeTripResult,
26	    ] = await Promise.all([
27	      adminClient
28	        .from("financial_contests")
29	        .select("id, name, contest_date, entry_fee")
30	        .order("contest_date", { ascending: false, nullsFirst: false }),
31	      adminClient
32	        .from("trip_settings")
33	        .select("id, trip_name, trip_year, start_date")
34	        .order("trip_year", { ascending: false }),
35	      adminClient
36	        .from("financial_transactions")
37	        .select("user_id, financial_contest_id, trip_id, type, amount, source, option_id"),
38	      adminClient
39	        .from("users")
40	        .select("id, display_name, full_name, avatar_url")
41	        .eq("is_system", false)
42	        .order("display_name"),
43	      adminClient
44	        .from("financial_contest_participants")
45	        .select("financial_contest_id, user_id"),
46	      adminClient
47	        .from("event_participants")
48	        .select("trip_id, user_id, likelihood"),
49	      adminClient
50	        .from("trip_settings")
51	        .select("id, trip_name, trip_year")
52	        .eq("id", (await getEffectiveTripId())!)
53	        .maybeSingle(),
54	    ]);
55	
56	    if (contestsResult.error) {
57	      return NextResponse.json({ error: contestsResult.error.message }, { status: 500 });
58	    }
59	    if (tripsResult.error) {
60	      return NextResponse.json({ error: tripsResult.error.message }, { status: 500 });
61	    }
62	    if (txnResult.error) {
63	      return NextResponse.json({ error: txnResult.error.message }, { status: 500 });
64	    }
65	    if (usersResult.error) {
66	      return NextResponse.json({ error: usersResult.error.message }, { status: 500 });
67	    }
68	
69	    const contests = contestsResult.data || [];
70	    const trips = tripsResult.data || [];
71	    // Recompute amounts on option-driven transactions from current cost_items
72	    // before aggregating, so balances reflect live prices.
73	    const transactions = await applyComputedTransactionAmounts(
74	      adminClient,
75	      txnResult.data || [],
76	    );
77	    const allUsers = usersResult.data || [];
78	
79	    // Build participation sets
80	    const contestParticipants: Record<string, string[]> = {};
81	    for (const cp of contestParticipantsResult.data || []) {
82	      if (!contestParticipants[cp.financial_contest_id]) {
83	        contestParticipants[cp.financial_contest_id] = [];
84	      }
85	      contestParticipants[cp.financial_contest_id].push(cp.user_id);
86	    }
87	
88	    const eventParticipants: Record<string, string[]> = {};
89	    const activeTrip = activeTripResult.data || null;
90	    const activeAttending: string[] = [];
91	    for (const ep of eventParticipantsResult.data || []) {
92	      if (!eventParticipants[ep.trip_id]) {
93	        eventParticipants[ep.trip_id] = [];
94	      }
95	      eventParticipants[ep.trip_id].push(ep.user_id);
96	      if (activeTrip && ep.trip_id === activeTrip.id && ep.likelihood === 99) {
97	        activeAttending.push(ep.user_id);
98	      }
99	    }
100	
101	    // Aggregate per-user totals, per-contest balances, and per-trip balances
102	    const userAgg = new Map<string, { charges: number; payments: number }>();
103	    const contestBalances: Record<string, Record<string, number>> = {};
104	    const tripBalances: Record<string, Record<string, number>> = {};
105	    const uncategorized: Record<string, number> = {};
106	
107	    for (const t of transactions) {
108	      // Per-user lifetime totals
109	      const agg = userAgg.get(t.user_id) || { charges: 0, payments: 0 };
110	      const amt = Number(t.amount);
111	      if (t.type === "charge") agg.charges += amt;
112	      else agg.payments += amt;
113	      userAgg.set(t.user_id, agg);
114	
115	      const delta = t.type === "payment" ? amt : -amt;
116	
117	      // Per-user per-contest net balance
118	      if (t.financial_contest_id) {
119	        if (!contestBalances[t.user_id]) contestBalances[t.user_id] = {};
120	        contestBalances[t.user_id][t.financial_contest_id] =
121	          (contestBalances[t.user_id][t.financial_contest_id] || 0) + delta;
122	      }
123	
124	      // Per-user per-trip net balance
125	      if (t.trip_id) {
126	        if (!tripBalances[t.user_id]) tripBalances[t.user_id] = {};
127	        tripBalances[t.user_id][t.trip_id] =
128	          (tripBalances[t.user_id][t.trip_id] || 0) + delta;
129	      }
130	
131	      // Per-user uncategorized balance (no trip, no contest)
132	      if (!t.trip_id && !t.financial_contest_id) {
133	        if (!uncategorized[t.user_id]) uncategorized[t.user_id] = 0;
134	        uncategorized[t.user_id] += delta;
135	      }
136	    }
137	
138	    // Round balances
139	    for (const userId of Object.keys(contestBalances)) {
140	      for (const key of Object.keys(contestBalances[userId])) {
141	        contestBalances[userId][key] = Number(contestBalances[userId][key].toFixed(2));
142	      }
143	    }
144	    for (const userId of Object.keys(tripBalances)) {
145	      for (const key of Object.keys(tripBalances[userId])) {
146	        tripBalances[userId][key] = Number(tripBalances[userId][key].toFixed(2));
147	      }
148	    }
149	    for (const userId of Object.keys(uncategorized)) {
150	      uncategorized[userId] = Number(uncategorized[userId].toFixed(2));
151	    }
152	
153	    // Build user list — all users, with their financial summaries
154	    const users = allUsers.map((u) => {
155	      const agg = userAgg.get(u.id) || { charges: 0, payments: 0 };
156	      return {
157	        user_id: u.id,
158	        display_name: u.display_name,
159	        full_name: u.full_name,
160	        avatar_url: u.avatar_url,
161	        total_charges: Number(agg.charges.toFixed(2)),
162	        total_payments: Number(agg.payments.toFixed(2)),
163	        balance: Number((agg.payments - agg.charges).toFixed(2)),
164	      };
165	    });
166	
167	    return NextResponse.json({
168	      contests,
169	      trips,
170	      users,
171	      contest_balances: contestBalances,
172	      trip_balances: tripBalances,
173	      contest_participants: contestParticipants,
174	      event_participants: eventParticipants,
175	      uncategorized,
176	      active_trip: activeTrip,
177	      active_trip_attending: activeAttending,
178	    });
179	  } catch (error) {
180	    console.error("Balances error:", error);
181	    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
182	  }
183	}
