6	// GET - Full transaction history for a single user
7	export async function GET(request: Request) {
8	  const admin = await checkPermissionAccess("manage_finances");
9	  if (!admin) {
10	    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
11	  }
12	
13	  const { searchParams } = new URL(request.url);
14	  const userId = searchParams.get("user_id");
15	
16	  if (!userId) {
17	    return NextResponse.json({ error: "user_id is required" }, { status: 400 });
18	  }
19	
20	  try {
21	    const adminClient = createAdminClient();
22	
23	    const [txnResult, historyResult] = await Promise.all([
24	      adminClient
25	        .from("financial_transactions")
26	        .select(
27	          "id, user_id, option_id, trip_id, financial_contest_id, type, source, description, amount, method, notes, created_by, created_at, trip:trip_settings!financial_transactions_trip_id_fkey(trip_name), contest:financial_contests!financial_transactions_financial_contest_id_fkey(name), creator:users!financial_transactions_created_by_fkey(display_name)"
28	        )
29	        .eq("user_id", userId)
30	        .order("created_at", { ascending: false }),
31	      adminClient
32	        .from("financial_transaction_history")
33	        .select("transaction_id, changed_by, changed_at, changer:users!financial_transaction_history_changed_by_fkey(display_name)")
34	        .order("changed_at", { ascending: false }),
35	    ]);
36	
37	    if (txnResult.error) {
38	      return NextResponse.json({ error: txnResult.error.message }, { status: 500 });
39	    }
40	
41	    // Recompute amounts on option-driven transactions from current cost_items.
42	    const recomputed = await applyComputedTransactionAmounts(adminClient, txnResult.data || []);
43	
44	    // Build map: transaction_id -> most recent editor (first entry per txn since sorted desc)
45	    const lastEditorMap = new Map<string, { name: string; has_history: boolean }>();
46	    for (const h of historyResult.data || []) {
47	      if (!lastEditorMap.has(h.transaction_id)) {
48	        const changerName = (h.changer as unknown as { display_name: string } | null)?.display_name ?? null;
49	        lastEditorMap.set(h.transaction_id, {
50	          name: changerName || "Unknown",
51	          has_history: true,
52	        });
53	      }
54	    }
55	
56	    const formatted = recomputed.map((t) => {
57	      const editor = lastEditorMap.get(t.id);
58	      const creatorName = (t.creator as unknown as { display_name: string } | null)?.display_name ?? null;
59	
60	      return {
61	        id: t.id,
62	        trip_id: t.trip_id,
63	        trip_name: (t.trip as unknown as { trip_name: string } | null)?.trip_name ?? null,
64	        financial_contest_id: (t as Record<string, unknown>).financial_contest_id ?? null,
65	        contest_name: (t.contest as unknown as { name: string } | null)?.name ?? null,
66	        type: t.type,
67	        source: t.source,
68	        description: t.description,
69	        amount: Number(t.amount),
70	        method: t.method,
71	        notes: t.notes,
72	        created_by: t.created_by,
73	        created_by_name: creatorName,
74	        // Show last editor if edited, otherwise the creator
75	        attributed_to: editor ? editor.name : creatorName,
76	        has_history: editor?.has_history ?? false,
77	        created_at: t.created_at,
78	      };
79	    });
80	
81	    return NextResponse.json({ transactions: formatted });
82	  } catch (error) {
83	    console.error("Financial ledger error:", error);
84	    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
85	  }
86	}
