6	// Sources admins can set via this API. System sources (option,
7	// contest_entry) are written by their own subsystems; 'manual' and
8	// 'adjustment' remain legal so legacy flows / bookkeeping fixes still work.
9	const ADMIN_SOURCES = [
10	  "deposit",
11	  "withdrawal",
12	  "winnings",
13	  "credit",
14	  "expense",
15	  "manual",
16	  "adjustment",
17	] as const;
18	type AdminSource = (typeof ADMIN_SOURCES)[number];
19	
20	const SOURCE_REQUIRED_TYPE: Partial<Record<AdminSource, "charge" | "payment">> = {
21	  deposit: "payment",
22	  winnings: "payment",
23	  credit: "payment",
24	  withdrawal: "charge",
25	  expense: "charge",
26	};
27	
28	function validateSource(
29	  source: string | undefined | null,
30	  type: "charge" | "payment",
31	  financial_contest_id: string | null,
32	  trip_id: string | null
33	): { ok: true; source: AdminSource } | { ok: false; error: string } {
34	  const s = (source || "manual") as AdminSource;
35	  if (!ADMIN_SOURCES.includes(s)) {
36	    return { ok: false, error: `source must be one of ${ADMIN_SOURCES.join(", ")}` };
37	  }
38	  const required = SOURCE_REQUIRED_TYPE[s];
39	  if (required && required !== type) {
40	    return { ok: false, error: `source '${s}' requires type '${required}'` };
41	  }
42	  if (s === "winnings" && !financial_contest_id) {
43	    return { ok: false, error: "winnings require a financial_contest_id" };
44	  }
45	  if (s === "withdrawal" && (financial_contest_id || trip_id)) {
46	    return { ok: false, error: "withdrawals cannot be assigned to an event" };
47	  }
48	  return { ok: true, source: s };
49	}
