51	// POST - Create a manual transaction
52	export async function POST(request: Request) {
53	  const admin = await checkPermissionAccess("manage_finances");
54	  if (!admin) {
55	    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
56	  }
57	
58	  try {
59	    const body = await request.json();
60	    const { user_id, trip_id, type, description, amount, method, notes, financial_contest_id, source } = body;
61	
62	    // Validate required fields
63	    if (!user_id || !type || !description || amount == null) {
64	      return NextResponse.json(
65	        { error: "user_id, type, description, and amount are required" },
66	        { status: 400 }
67	      );
68	    }
69	
70	    if (type !== "charge" && type !== "payment") {
71	      return NextResponse.json(
72	        { error: "type must be 'charge' or 'payment'" },
73	        { status: 400 }
74	      );
75	    }
76	
77	    if (typeof amount !== "number" || amount <= 0) {
78	      return NextResponse.json(
79	        { error: "amount must be a number greater than 0" },
80	        { status: 400 }
81	      );
82	    }
83	
84	    const sourceCheck = validateSource(source, type, financial_contest_id || null, trip_id || null);
85	    if (!sourceCheck.ok) {
86	      return NextResponse.json({ error: sourceCheck.error }, { status: 400 });
87	    }
88	
89	    // Get the authenticated user's id for created_by
90	    const supabase = await createClient();
91	    const {
92	      data: { user },
93	    } = await supabase.auth.getUser();
94	
95	    if (!user) {
96	      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
97	    }
98	
99	    const adminClient = createAdminClient();
100	
101	    const { data: transaction, error } = await adminClient
102	      .from("financial_transactions")
103	      .insert({
104	        user_id,
105	        trip_id: trip_id || null,
106	        type,
107	        source: sourceCheck.source,
108	        option_id: null,
109	        financial_contest_id: financial_contest_id || null,
110	        description,
111	        amount,
112	        method: method || null,
113	        notes: notes || null,
114	        created_by: user.id,
115	      })
116	      .select()
117	      .single();
118	
119	    if (error) {
120	      return NextResponse.json({ error: error.message }, { status: 500 });
121	    }
122	
123	    return NextResponse.json(transaction, { status: 201 });
124	  } catch (error) {
125	    console.error("Create transaction error:", error);
126	    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
127	  }
128	}
