130	// PUT - Update a transaction (manual: all fields; option-derived: amount only)
131	export async function PUT(request: Request) {
132	  const admin = await checkPermissionAccess("manage_finances");
133	  if (!admin) {
134	    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
135	  }
136	
137	  try {
138	    const body = await request.json();
139	    const { id, type, description, amount, method, notes, financial_contest_id } = body;
140	
141	    if (!id) {
142	      return NextResponse.json({ error: "id is required" }, { status: 400 });
143	    }
144	
145	    const adminClient = createAdminClient();
146	
147	    // Get the authenticated user for audit trail
148	    const supabase = await createClient();
149	    const {
150	      data: { user },
151	    } = await supabase.auth.getUser();
152	
153	    if (!user) {
154	      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
155	    }
156	
157	    const { data: existing, error: fetchError } = await adminClient
158	      .from("financial_transactions")
159	      .select("id, source, type, description, amount, method, notes, financial_contest_id, trip_id")
160	      .eq("id", id)
161	      .single();
162	
163	    if (fetchError || !existing) {
164	      return NextResponse.json({ error: "Transaction not found" }, { status: 404 });
165	    }
166	
167	    const isOption = existing.source === "option";
168	
169	    // Build update object from provided fields
170	    const updates: Record<string, unknown> = {};
171	
172	    // Amount is editable for all transactions
173	    if (amount !== undefined) {
174	      if (typeof amount !== "number" || amount <= 0) {
175	        return NextResponse.json({ error: "amount must be a number greater than 0" }, { status: 400 });
176	      }
177	      updates.amount = amount;
178	    }
179	
180	    // Other fields only editable on manual transactions
181	    if (!isOption) {
182	      if (type !== undefined) {
183	        if (type !== "charge" && type !== "payment") {
184	          return NextResponse.json({ error: "type must be 'charge' or 'payment'" }, { status: 400 });
185	        }
186	        updates.type = type;
187	      }
188	      if (description !== undefined) updates.description = description;
189	      if (method !== undefined) updates.method = method || null;
190	      if (notes !== undefined) updates.notes = notes || null;
191	      if (financial_contest_id !== undefined) updates.financial_contest_id = financial_contest_id || null;
192	
193	      // Re-validate source against any changed type / financial_contest_id
194	      const nextType = (updates.type as "charge" | "payment") ?? existing.type;
195	      const nextContestId =
196	        "financial_contest_id" in updates
197	          ? (updates.financial_contest_id as string | null)
198	          : existing.financial_contest_id;
199	      const sourceCheck = validateSource(
200	        existing.source,
