247	// DELETE - Delete a manual transaction (cannot delete option-derived)
248	export async function DELETE(request: Request) {
249	  const admin = await checkPermissionAccess("manage_finances");
250	  if (!admin) {
251	    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
252	  }
253	
254	  try {
255	    const body = await request.json();
256	    const { id } = body;
257	
258	    if (!id) {
259	      return NextResponse.json({ error: "id is required" }, { status: 400 });
260	    }
261	
262	    const supabase = await createClient();
263	    const {
264	      data: { user },
265	    } = await supabase.auth.getUser();
266	
267	    if (!user) {
268	      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
269	    }
270	
271	    const adminClient = createAdminClient();
272	
273	    // Check that the transaction exists and is not option-derived
274	    const { data: existing, error: fetchError } = await adminClient
275	      .from("financial_transactions")
276	      .select("id, source, type, description, amount, method, notes, financial_contest_id, trip_id")
277	      .eq("id", id)
278	      .single();
279	
280	    if (fetchError || !existing) {
281	      return NextResponse.json({ error: "Transaction not found" }, { status: 404 });
282	    }
283	
284	    if (existing.source === "option") {
285	      return NextResponse.json(
286	        { error: "Cannot delete option-derived transactions. Manage these through the selection system." },
287	        { status: 403 }
288	      );
289	    }
290	
291	    if (existing.source === "contest_entry") {
292	      return NextResponse.json(
293	        { error: "Cannot delete contest entry transactions. Manage these through the contest participant system." },
294	        { status: 403 }
295	      );
296	    }
297	
298	    // Log history before deleting
299	    await adminClient.from("financial_transaction_history").insert({
300	      transaction_id: id,
301	      action: "delete",
302	      changed_by: user.id,
303	      previous_type: existing.type,
304	      previous_source: existing.source,
305	      previous_description: existing.description,
306	      previous_amount: existing.amount,
307	      previous_method: existing.method,
308	      previous_notes: existing.notes,
309	      previous_financial_contest_id: existing.financial_contest_id,
310	      previous_trip_id: existing.trip_id,
311	    });
312	
313	    const { error: deleteError } = await adminClient
314	      .from("financial_transactions")
315	      .delete()
316	      .eq("id", id);
317	
318	    if (deleteError) {
319	      return NextResponse.json({ error: deleteError.message }, { status: 500 });
320	    }
321	
322	    return NextResponse.json({ success: true });
323	  } catch (error) {
324	    console.error("Delete transaction error:", error);
325	    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
326	  }
327	}
