6	// GET - Transactions for a specific user + financial contest, trip, or uncategorized
7	export async function GET(request: Request) {
8	  const admin = await checkPermissionAccess("manage_finances");
9	  if (!admin) {
10	    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
11	  }
12	
13	  const { searchParams } = new URL(request.url);
14	  const userId = searchParams.get("user_id");
15	  const contestId = searchParams.get("financial_contest_id");
16	  const tripId = searchParams.get("trip_id");
17	  const uncategorized = searchParams.get("uncategorized");
18	
19	  if (!userId || (!contestId && !tripId && !uncategorized)) {
20	    return NextResponse.json(
21	      { error: "user_id and either financial_contest_id, trip_id, or uncategorized are required" },
22	      { status: 400 }
23	    );
24	  }
25	
26	  try {
27	    const adminClient = createAdminClient();
28	
29	    let query = adminClient
30	      .from("financial_transactions")
31	      .select(
32	        "id, user_id, option_id, type, source, description, amount, method, notes, created_at, created_by, creator:users!financial_transactions_created_by_fkey(display_name)"
33	      )
34	      .eq("user_id", userId);
35	
36	    if (uncategorized) {
37	      query = query.is("financial_contest_id", null).is("trip_id", null);
38	    } else if (contestId) {
39	      query = query.eq("financial_contest_id", contestId);
40	    } else if (tripId) {
41	      query = query.eq("trip_id", tripId);
42	    }
43	
44	    const { data: transactions, error } = await query.order("created_at", { ascending: false });
45	
46	    if (error) {
47	      return NextResponse.json({ error: error.message }, { status: 500 });
48	    }
49	
50	    // Recompute amounts on option-driven transactions from current cost_items.
51	    const recomputed = await applyComputedTransactionAmounts(adminClient, transactions || []);
52	
53	    // Fetch history for these transactions
54	    const txnIds = recomputed.map((t) => t.id);
55	    let lastEditorMap = new Map<string, { name: string; has_history: boolean }>();
56	
57	    if (txnIds.length > 0) {
58	      const { data: history } = await adminClient
