60	        .select("transaction_id, changed_by, changed_at, changer:users!financial_transaction_history_changed_by_fkey(display_name)")
61	        .in("transaction_id", txnIds)
62	        .order("changed_at", { ascending: false });
63	
64	      for (const h of history || []) {
