77	      const creatorName = (t.creator as unknown as { display_name: string } | null)?.display_name ?? null;
78	
79	      return {
80	        ...t,
81	        creator: undefined,
82	        created_by_name: creatorName,
83	        attributed_to: editor ? editor.name : creatorName,
